-- Carga reconciliada de acessórios W.Vetro com unidade de origem UN.
-- Fonte: Reconciliacao_ExportWWAcessorios_Atlas.xlsx, aba Reconciliacao.
-- Pré-requisito: 20260816210000_produtos_identidade_tecnica_v1.sql aplicada.
--
-- Escopo deliberadamente conservador:
--   - 785 acessórios faltantes na reconciliação;
--   - 649 possuem UN Fonte = 'UN' e entram nesta migration;
--   - 136 com MT/PR/BR/PC/CJ/TB/M2/CT/RO ficam fora até validação da
--     unidade operacional de consumo do Atlas.
--
-- Regras:
--   - nenhum preço/custo é inventado: preco permanece 0 como placeholder,
--     porque a fonte não contém preço/custo;
--   - linha/cor da origem ficam apenas em dados_origem, sem criar vínculos
--     técnicos linha_id/cor_id;
--   - ncm_origem preserva o valor cru; ncm só recebe valor quando há 8 dígitos
--     e não é placeholder conhecido; mesmo assim ncm_status fica 'pendente';
--   - id_externo_wvetro permanece NULL porque a planilha não fornece uma chave
--     externa distinta do código técnico;
--   - status_validacao = 'importado': nenhum item passa a ser tecnicamente
--     validado automaticamente.

begin;

create temporary table _carga_acessorios_wvetro_un (
  codigo_origem_raw text not null,
  descricao_fonte text not null,
  unidade_fonte text not null,
  ncm_fonte text,
  linha_origem text,
  cor_origem text,
  fabricante_origem text,
  flags_revisao text,
  status_fonte text,
  motivos_fonte text,
  qtde_embalagem numeric,
  ativo_fonte text
) on commit drop;

insert into _carga_acessorios_wvetro_un (
  codigo_origem_raw,
