-- Guardas: se a base mudou desde a reconciliação, abortar em vez de sobrescrever.
do $$
declare
  v_total integer;
  v_duplicados integer;
  v_unidades_invalidas integer;
  v_inativos integer;
  v_colisoes integer;
begin
  select count(*) into v_total from _carga_acessorios_wvetro_un;
  if v_total <> 649 then
    raise exception 'Carga W.Vetro UN esperava 649 linhas; encontrou %', v_total;
  end if;

  select count(*) into v_duplicados
  from (
    select upper(regexp_replace(trim(codigo_origem_raw), '\s+', ' ', 'g')) as codigo_norm
    from _carga_acessorios_wvetro_un
    group by 1
    having count(*) > 1
  ) d;
  if v_duplicados <> 0 then
    raise exception 'Carga W.Vetro UN contém % código(s) normalizado(s) duplicado(s)', v_duplicados;
  end if;

  select count(*) into v_unidades_invalidas
  from _carga_acessorios_wvetro_un
  where upper(trim(unidade_fonte)) <> 'UN';
  if v_unidades_invalidas <> 0 then
    raise exception 'Carga W.Vetro UN contém % linha(s) com unidade diferente de UN', v_unidades_invalidas;
  end if;

  select count(*) into v_inativos
  from _carga_acessorios_wvetro_un
  where lower(trim(coalesce(ativo_fonte, ''))) not in ('sim', 'true', '1', 't');
  if v_inativos <> 0 then
    raise exception 'Carga W.Vetro UN contém % item(ns) não ativos na fonte', v_inativos;
  end if;

  select count(*) into v_colisoes
  from _carga_acessorios_wvetro_un c
  join public.produtos p
    on upper(p.codigo) = upper(regexp_replace(trim(c.codigo_origem_raw), '\s+', ' ', 'g'));
  if v_colisoes <> 0 then
    raise exception 'Base mudou desde a reconciliação: % código(s) da carga já existem em produtos', v_colisoes;
  end if;
end $$;

insert into public.produtos (
  nome,
  categoria,
  preco,
  unidade,
  descricao,
  ativo,
  marca,
  ncm,
  codigo,
  codigo_origem,
  origem,
  id_externo_wvetro,
  unidade_origem,
  qtde_embalagem_origem,
  dados_origem,
  status_validacao,
  observacao_validacao,
  ncm_origem,
  ncm_status
)
select
  regexp_replace(upper(trim(c.codigo_origem_raw)), '\s+', ' ', 'g')
    || ' - ' || trim(c.descricao_fonte) as nome,
  'acessorio' as categoria,
  0 as preco,
  'UN' as unidade,
  trim(c.descricao_fonte) as descricao,
  true as ativo,
  nullif(trim(c.fabricante_origem), '') as marca,
  case
    when trim(coalesce(c.ncm_fonte, '')) ~ '^[0-9]{8}$'
      and trim(c.ncm_fonte) not in ('12345678', '12345667')
    then trim(c.ncm_fonte)
    else null
  end as ncm,
  regexp_replace(upper(trim(c.codigo_origem_raw)), '\s+', ' ', 'g') as codigo,
  c.codigo_origem_raw as codigo_origem,
  'wvetro' as origem,
  null as id_externo_wvetro,
  trim(c.unidade_fonte) as unidade_origem,
  c.qtde_embalagem as qtde_embalagem_origem,
  jsonb_build_object(
    'fonte', 'ExportWWAcessorios.xlsx',
    'reconciliacao', '2026-08-16/17',
    'codigo_raw', c.codigo_origem_raw,
    'descricao_raw', c.descricao_fonte,
    'unidade_raw', c.unidade_fonte,
    'ncm_raw', c.ncm_fonte,
    'linha_raw', c.linha_origem,
    'cor_raw', c.cor_origem,
    'fabricante_raw', c.fabricante_origem,
    'qtde_emb_raw', c.qtde_embalagem,
    'ativo_raw', c.ativo_fonte,
    'status_fonte', c.status_fonte,
    'motivos_fonte', c.motivos_fonte,
    'flags_revisao', c.flags_revisao
  ) as dados_origem,
  'importado' as status_validacao,
  'Importado da base W.Vetro reconciliada. Preço/custo não disponíveis na fonte: preco=0 é placeholder. Linha e cor da origem não foram vinculadas automaticamente.' as observacao_validacao,
  nullif(trim(c.ncm_fonte), '') as ncm_origem,
  case
    when trim(coalesce(c.ncm_fonte, '')) in ('', '0', '12345678', '12345667')
      or trim(coalesce(c.ncm_fonte, '')) !~ '^[0-9]{8}$'
    then 'invalido'
    else 'pendente'
  end as ncm_status
from _carga_acessorios_wvetro_un c
order by regexp_replace(upper(trim(c.codigo_origem_raw)), '\s+', ' ', 'g');

do $$
declare
  v_inseridos integer;
begin
  select count(*) into v_inseridos
  from public.produtos
  where origem = 'wvetro'
    and categoria = 'acessorio'
    and upper(codigo) in (
      select upper(regexp_replace(trim(codigo_origem_raw), '\s+', ' ', 'g'))
      from _carga_acessorios_wvetro_un
    );

  if v_inseridos <> 649 then
    raise exception 'Pós-carga esperava encontrar 649 acessórios W.Vetro desta migration; encontrou %', v_inseridos;
  end if;
end $$;

commit;
